fied', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '10.1177/154193121005400903', NULL, NULL, NULL, NULL, 'https://doi.org/10.1177/154193121005400903', '2026-09-18', NULL, NULL, 1, 'clinical', 'KR', NULL, NULL, NULL, 'COMPLETE', 'VERIFIED', 'RESOLVED', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-18 21:34', 'session_2026-09-18-research-batch-17-vredenburgh-full-read-and-mining', '2026-09-18 21:38', 'session_2026-09-18-research-batch-17-vredenburgh-full-read-and-mining', 'crossref', NULL, 1, NULL, '698-702', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'high_control', 'captured', 'deferred', NULL, NULL, NULL, NULL, 'CLOSED', 'tool', NULL);
