-- source_value_extractions: 3 insert(s), 0 update(s)
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (49, 'REF-01003', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'US', NULL, 'absent', NULL, NULL, 'Paths meeting the proposed accessibility guidelines were rated as either easy or moderate for difficulty of use.', 'abstract', NULL, 'measurement_primary', 'REF-01003', NULL, 'field_observation', 'not_device_scoped', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'skim', 'preliminary', NULL, 'A SECOND confirms EDGE AGAINST A STANDARD, after REF-00980 -- and it states no value, so it is graded absent. THE POPULATION IS THE PROBLEM AND IT WAS PREDICTED BEFORE RETRIEVAL: the 23 participants had vision OR mobility limitations and WALKED at their preferred pace, so they are AMBULATORY, not wheelchair users. Graded PROXY for MOB, and the authors say so themselves -- their closing line calls for future work to examine different perceptions between ambulatory individuals and wheelchair users. THE SECOND FINDING IS THE MORE INTERESTING ONE and is recorded here rather than as its own row because it carries no value either: slopes exceeding the guidelines may also be acceptable for very short distances or on hard-paved surfaces. That is DISTANCE-CONDITIONING measured in the field -- the same structure as REF-01002 20 ft bound and REF-00996 stated mechanism, now from a third method. T3 by the ratified ladder (clinical + lower_control, a pilot field study with no control condition), so it CANNOT lift parameter 3 off proxy, which the priors recorded before retrieval so the temptation to grade it up is on the record.', '2026-09-18 21:35', 'session_2026-09-18-research-batch-17-vredenburgh-full-read-and-mining', '2026-09-18 21:35', 'session_2026-09-18-research-batch-17-vredenburgh-full-read-and-mining', 'finding', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (50, 'REF-01004', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'KR', NULL, 'range', '1:6 to 1:14', 'rise:run ratio', 'five levels of slope (1:6, 1:8, 1:10, 1:12 and 1:14) and three levels of height (15 cm, 30 cm and 45 cm) are considered', 'abstract', NULL, 'measurement_primary', 'REF-01004', NULL, 'instrumented_physical_measurement', 'manual_self_propelled', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'skim', 'preliminary', NULL, 'THE TESTED SLOPE SET -- AN EXPERIMENTAL CONDITION, NOT A CLAIM, and figure_role says so. Same guard as REF-00979 tested set: a tested slope read as a claim is how a range no source asserted reached extraction 1.', '2026-09-18 21:35', 'session_2026-09-18-research-batch-17-vredenburgh-full-read-and-mining', '2026-09-18 21:35', 'session_2026-09-18-research-batch-17-vredenburgh-full-read-and-mining', 'condition', 'between');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (51, 'REF-01004', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'KR', NULL, 'numerical', '1:8', 'rise:run ratio', 'slope effects were minor at a low height; thus, a slope of 1:8 can be recommended if the installation space for a gentler ramp is not sufficient', 'abstract (Results)', NULL, 'measurement_primary', 'REF-01004', NULL, 'instrumented_physical_measurement', 'manual_self_propelled', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'skim', 'preliminary', NULL, 'A SECOND ANCHORING-TIER STATED VALUE FOR THIS PARAMETER, AND IT POINTS THE OPPOSITE WAY FROM THE FIRST. REF-01002 says a ramp should not exceed 7 percent (about 1:14) for a 20 ft transit; this says 1:8 (12.5 percent) can be recommended -- but ONLY under two conditions the source states together and which must never be separated from it: LOW RISE HEIGHT, and insufficient installation space for a gentler ramp. So the two are not in conflict once their conditions are read: REF-01002 conditions on DISTANCE, this conditions on RISE, and REF-00996 gives rise-conditioning as the MECHANISM (the greater the height difference, the gentler the ramp must be, because the effort must be sustained longer). THREE SOURCES, THREE METHODS, ONE CONDITIONING STRUCTURE, and this is the first to measure the rise half rather than state it. THE OVER-READ TO GUARD AGAINST is quoting 1:8 as a permissive maximum: the same abstract reports NO SIGNIFICANT DIFFERENCE BETWEEN 1:10 AND 1:12 (as suggested by ADAAG), so the paper is not arguing for steeper ramps generally -- it is saying the code distinction is not detectable at low rise and that a steeper ramp is tolerable when the rise is small. extraction_method SKIM on a deposited abstract; the full text is not read and the participant count is not stated in it.', '2026-09-18 21:36', 'session_2026-09-18-research-batch-17-vredenburgh-full-read-and-mining', '2026-09-18 21:36', 'session_2026-09-18-research-batch-17-vredenburgh-full-read-and-mining', 'claim', '<=');

